/* @lc app=leetcode id=2763 lang=kotlin */ class Solution { fun sumImbalanceNumbers(nums: IntArray): Int = nums.indices.sumOf { i -> BooleanArray(nums.size + 2).let { pr -> (i until nums.size).fold(Triple(0, 0, 0)) { (d, c, tot), j -> nums[j].let { x -> if (pr[x]) Triple(d, c, tot + d - 1 - c) else (d + 1).let { d2 -> (c + (if (pr[x - 1]) 1 else 0) + (if (pr[x + 1]) 1 else 0)).let { c2 -> true.also { pr[x] = true }.let { Triple(d2, c2, tot + d2 - 1 - c2) } } } } }.third } } }